DO $$
DECLARE n INTEGER;
BEGIN
  SELECT COUNT(*) INTO n FROM _saldo_wik;
  IF n <> 74 THEN
    RAISE EXCEPTION 'Esperava 74 referências confirmadas pelo relatório de saldo, vieram %. Migration abortada.', n;
  END IF;
END $$;

-- Só toca em quem ainda está com unidade DEDUZIDA. Se alguém já confirmou a
-- unidade na tela (unidade_confianca IS NULL), a decisão da pessoa vence — ela
-- pode saber de algo que nem o relatório sabe.
UPDATE insumos i
   SET unidade = s.unidade,
       unidade_confianca = NULL,
       tipo = COALESCE(s.tipo, i.tipo),
       fornecedor_id = COALESCE(
         i.fornecedor_id,
         (SELECT f.id FROM fornecedores f
           WHERE upper(btrim(f.nome)) = upper(btrim(s.fornecedor_nome))
           ORDER BY f.id LIMIT 1)),
       observacoes = COALESCE(NULLIF(i.observacoes, ''), '') ||
         CASE WHEN COALESCE(i.observacoes, '') = '' THEN '' ELSE E'\n' END || s.observacoes,
       atualizado_em = now()
  FROM _saldo_wik s
 WHERE s.codigo = i.codigo
   AND i.unidade_confianca IS NOT NULL;

-- ---------------------------------------------------------------------------
-- 2. Os 63 que continuam sem prova, mas cuja dedução mudou com as regras
--    corrigidas. Mesma trava: quem já foi confirmado por gente não é tocado,
--    e quem acabou de ser confirmado pelo relatório acima também não (o
--    UPDATE anterior já zerou o `unidade_confianca` deles).
-- ---------------------------------------------------------------------------
CREATE TEMP TABLE _reclass_wik (
  codigo      VARCHAR(60),
  unidade     VARCHAR(20),
  tipo        VARCHAR(30),
  confianca   VARCHAR(20),
  observacoes TEXT
) ON COMMIT DROP;

