UPDATE insumos i
   SET unidade = r.unidade,
       tipo = r.tipo,
       unidade_confianca = r.confianca,
       observacoes = COALESCE(NULLIF(i.observacoes, ''), '') ||
         CASE WHEN COALESCE(i.observacoes, '') = '' THEN '' ELSE E'\n' END || r.observacoes,
       atualizado_em = now()
  FROM _reclass_wik r
 WHERE r.codigo = i.codigo
   AND i.unidade_confianca IS NOT NULL;
